contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the caller address to attempt the suicide and an amount
    // We cannot control msg.sender for calls into c since this contract is the caller; instead
    // we observe smartfix_owner getter and compare it to address(this) to decide expected behavior.
    function run(uint topUp) public payable {
        require(address(this).balance >= topUp);

        // Fund the contract C so there is some balance to transfer on selfdestruct
        if (topUp > 0) {
            // send Ether to c
            (bool sent, ) = address(c).call{value: topUp}("");
            require(sent);
        }

        // Read observable before-values
        address owner = c.smartfix_owner();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // Try calling sudicideAnyone and record whether it reverted
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (some may be 0 if selfdestruct happened)
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // General rule:
        // - If this contract is the smartfix_owner, the call must NOT revert and all ETH held by c before
        //   must be transferred to this contract (so afterThisBalance >= beforeThisBalance + beforeCBalance and afterCBalance == 0).
        // - If this contract is NOT the smartfix_owner, the call must revert and balances must be unchanged.
        assert(
            (owner == address(this) && reverted == false && afterCBalance == 0 && afterThisBalance >= beforeThisBalance + beforeCBalance)
            ||
            (owner != address(this) && reverted == true && afterCBalance == beforeCBalance && afterThisBalance == beforeThisBalance)
        );
    }

    // allow receiving ETH from selfdestruct
    receive() external payable {}
}

