contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the caller address as parameter by simulating through delegate call pattern is impossible,
    // but msg.sender for calls from this contract is fixed. We therefore take an arbitrary address 'caller' and assert that
    // if caller != smartfix_owner then calling sudicideAnyone from this contract must revert and thus not change c's balance.
    // We achieve this by: recording owner and balance before, attempting the call, catching revert, and then asserting
    // that (caller != owner) implies (call reverted and balance unchanged) and (caller == owner) implies (call did not revert).

    function run(address caller, uint256 sendAmount) public payable {
        require(true);
        // ensure this contract has enough balance if we plan to send any Ether to c (not needed here, but safe)
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
        }

        // observe owner and balance before
        address ownerBefore = c.smartfix_owner();
        uint256 balanceBefore = address(c).balance;

        // attempt the call and record whether it reverted
        bool reverted;
        try c.sudicideAnyone{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General invariant: if the caller (which in reality is this contract) is not the owner, the call must revert and balance unchanged;
        // if the caller equals owner, the call should not revert (and may selfdestruct, but then revert==false still holds when call returns).
        // We express caller equivalence via the observed ownerBefore value compared to the implicit caller (this contract).
        // The rule is: (ownerBefore != address(this)) => (reverted == true && balanceAfter == balanceBefore)
        // and (ownerBefore == address(this)) => reverted == false

        assert(
            (ownerBefore != address(this) ? (reverted && balanceAfter == balanceBefore) : (!reverted))
        );
    }

    receive() external payable {}
}

